t" id="height" type="number" min="1" step="0.1" placeholder="Height cm"></div><button class="btn" id="calc">Calculate</button><div class="out" id="out"></div></section><aside class="tools"><h3>🛠️ All Tools</h3><?php $items=['image-compressor.php'=>'🖼️ Image Compressor','image-resizer.php'=>'📐 Image Resizer','jpg-to-png.php'=>'↩️ JPG to PNG','png-to-jpg.php'=>'↩️ PNG to JPG','word-counter.php'=>'📝 Word Counter','case-converter.php'=>'🔤 Case Converter','qr-generator.php'=>'🔐 QR Code Generator','password-generator.php'=>'🔑 Password Generator','json-formatter.php'=>'{} JSON Formatter','url-encoder.php'=>'🔗 URL Encoder','pdf-to-jpg.php'=>'📄 PDF to JPG','duplicate-line-remover.php'=>'🖌️ Duplicate Line Remover','image-cropper.php'=>'✂️ Image Cropper','image-rotator.php'=>'🔄 Image Rotator','gif-maker.php'=>'🎞️ GIF Maker','gif-to-jpg.php'=>'🖼️ GIF to JPG','jpg-to-webp.php'=>'🖼️ JPG to WebP','png-to-webp.php'=>'🖼️ PNG to WebP','pdf-to-png.php'=>'📄 PDF to PNG','pdf-merger.php'=>'📑 PDF Merger','pdf-splitter.php'=>'📄 PDF Splitter','pdf-compressor.php'=>'📦 PDF Compressor','age-calculator.php'=>'🎂 Age Calculator','percentage-calculator.php'=>'% Percentage Calculator','unit-converter.php'=>'📏 Unit Converter','stopwatch-timer.php'=>'⏱️ Stopwatch Timer'];foreach($items as $f=>$n):?><a class="<?=basename($_SERVER['SCRIPT_NAME'])===$f?'active':''?>" href="/smart-toolz/tools/<?=htmlspecialchars($f,ENT_QUOTES,'UTF-8')?>"><?=htmlspecialchars($n)?></a><?php endforeach;?><a href="/smart-toolz/tool.php">View All Tools →</a></aside></div></main><?php require_once __DIR__.'/../footer.php';?><script>document.getElementById('calc').onclick=()=>{const w=+document.getElementById('weight').value,h=+document.getElementById('height').value/100,o=document.getElementById('out');if(!w||!h||h<=0){o.textContent='Enter a valid weight and height.';return}const bmi=w/(h*h),cat=bmi<18.5?'Underweight':bmi<25?'Normal weight':bmi<30?'Overweight':'Obesity';o.innerHTML='<strong>BMI: '+bmi.toFixed(1)+'</strong><br>